// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, Easing, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('Inter');

// Module-level Google Font loading
const { fontFamily } = loadFont();



export type VennDiagramProps = Record<string, any>;

const VennDiagram: React.FC<VennDiagramProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 7,
  circleRadius = 230,
  circleStrokeWidth = 3,
  hypeColor = "#22c55e",
  communityColor = "#ffffff",
  relevanceColor = "#f87171", // Light red
  hypeLabel = "Hype",
  communityLabel = "Community",
  relevanceLabel = "Relevance",
  centerLabelLine1 = "Worth",
  centerLabelLine2 = "Investing In",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Resolve background color transparency
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Total frames and timeline phase markers scaled dynamically
  const totalFrames = durationInSeconds * fps;
  const t_hype_start = 0;
  const t_hype_end = Math.floor(totalFrames * (1.5 / 7));
  const t_comm_start = Math.floor(totalFrames * (1.5 / 7));
  const t_comm_end = Math.floor(totalFrames * (3.0 / 7));
  const t_rel_start = Math.floor(totalFrames * (3.0 / 7));
  const t_rel_end = Math.floor(totalFrames * (4.5 / 7));
  const t_settle_start = Math.floor(totalFrames * (4.5 / 7));
  const t_settle_end = Math.floor(totalFrames * (6.0 / 7));
  const t_center_start = Math.floor(totalFrames * (6.0 / 7));
  const t_center_end = totalFrames;

  // Center position of the canvas
  const cx = width / 2;
  const cy = height / 2;

  // Settle effect: circles slide inward closer together
  // Before settle: distance is wider. After settle: distance is tight.
  const d_start = circleRadius * 0.65;
  const d_end = circleRadius * 0.52;
  const d = interpolate(frame, [t_settle_start, t_settle_end], [d_start, d_end], {
    easing: Easing.bezier(0.16, 1, 0.3, 1),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Calculate coordinates of the three circle centers
  const cx1 = cx;
  const cy1 = cy - d;

  const cx2 = cx - d * 0.866;
  const cy2 = cy + d * 0.5;

  const cx3 = cx + d * 0.866;
  const cy3 = cy + d * 0.5;

  // Circle 1 (Hype) Animations
  const progress1 = interpolate(frame, [t_hype_start, t_hype_end], [0, 1], {
    easing: Easing.bezier(0.25, 1, 0.5, 1),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const label1Opacity = interpolate(frame, [t_hype_start + 12, t_hype_end], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const label1YOffset = interpolate(frame, [t_hype_start + 12, t_hype_end], [15, 0], {
    easing: Easing.out(Easing.quad),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Circle 2 (Community) Animations
  const progress2 = interpolate(frame, [t_comm_start, t_comm_end], [0, 1], {
    easing: Easing.bezier(0.25, 1, 0.5, 1),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const label2Opacity = interpolate(frame, [t_comm_start + 12, t_comm_end], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const label2Offset = interpolate(frame, [t_comm_start + 12, t_comm_end], [-15, 0], {
    easing: Easing.out(Easing.quad),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Circle 3 (Relevance) Animations
  const progress3 = interpolate(frame, [t_rel_start, t_rel_end], [0, 1], {
    easing: Easing.bezier(0.25, 1, 0.5, 1),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const label3Opacity = interpolate(frame, [t_rel_start + 12, t_rel_end], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const label3Offset = interpolate(frame, [t_rel_start + 12, t_rel_end], [15, 0], {
    easing: Easing.out(Easing.quad),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Central triple-overlap glowing spot animation
  const glowOpacity = interpolate(frame, [t_settle_start, t_settle_end], [0, 1], {
    easing: Easing.bezier(0.25, 1, 0.5, 1),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const glowScale = interpolate(frame, [t_settle_start, t_settle_end], [0.85, 1.05], {
    easing: Easing.out(Easing.quad),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Center Label Entrance
  const centerLabelOpacity = interpolate(frame, [t_center_start, t_center_end], [0, 1], {
    easing: Easing.out(Easing.quad),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const centerLabelScale = interpolate(frame, [t_center_start, t_center_end], [0.92, 1.0], {
    easing: Easing.bezier(0.175, 0.885, 0.32, 1.15),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Calculate perimeter for the trace paths
  const perimeter = 2 * Math.PI * circleRadius;

  // Specific label coordinate positioning - pushed further out for safety clearance
  const label1X = cx1;
  const label1Y = cy1 - circleRadius - 110; // Raised higher above the circle to match other text spacing

  const label2X = cx2 - circleRadius * 0.35;
  const label2Y = cy2 + circleRadius * 0.85 + 55; // Pushed lower below the circle

  const label3X = cx3 + circleRadius * 0.35;
  const label3Y = cy3 + circleRadius * 0.85 + 55; // Pushed lower below the circle

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {/* SVG Container for the Venn Circles */}
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        style={{ position: "absolute", top: 0, left: 0 }}
      >
        <defs>
          {/* Radial Gradient for the bright triple-overlap central region */}
          <radialGradient id="centerGlow" cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor="#22c55e" stopOpacity={0.8} />
            <stop offset="55%" stopColor="#22c55e" stopOpacity={0.25} />
            <stop offset="100%" stopColor="#22c55e" stopOpacity={0} />
          </radialGradient>
        </defs>

        {/* 1. Hype Circle */}
        <circle
          cx={cx1}
          cy={cy1}
          r={circleRadius}
          fill={hypeColor}
          fillOpacity={progress1 * 0.12}
          stroke={hypeColor}
          strokeWidth={circleStrokeWidth}
          strokeDasharray={perimeter}
          strokeDashoffset={perimeter * (1 - progress1)}
          style={{
            mixBlendMode: "screen",
            filter: `drop-shadow(0 0 10px ${hypeColor}55)`,
            transition: "none",
          }}
        />

        {/* 2. Community Circle */}
        <circle
          cx={cx2}
          cy={cy2}
          r={circleRadius}
          fill={communityColor}
          fillOpacity={progress2 * 0.08}
          stroke={communityColor}
          strokeWidth={circleStrokeWidth}
          strokeDasharray={perimeter}
          strokeDashoffset={perimeter * (1 - progress2)}
          style={{
            mixBlendMode: "screen",
            filter: `drop-shadow(0 0 10px ${communityColor}33)`,
            transition: "none",
          }}
        />

        {/* 3. Relevance Circle (Grey Color style automatically flows here) */}
        <circle
          cx={cx3}
          cy={cy3}
          r={circleRadius}
          fill={relevanceColor}
          fillOpacity={progress3 * 0.12}
          stroke={relevanceColor}
          strokeWidth={circleStrokeWidth}
          strokeDasharray={perimeter}
          strokeDashoffset={perimeter * (1 - progress3)}
          style={{
            mixBlendMode: "screen",
            filter: `drop-shadow(0 0 10px ${relevanceColor}55)`,
            transition: "none",
          }}
        />

        {/* 4. Central Overlap Glow Effect */}
        {glowOpacity > 0 && (
          <circle
            cx={cx}
            cy={cy}
            r={circleRadius * 0.6}
            fill="url(#centerGlow)"
            style={{
              opacity: glowOpacity,
              transform: `scale(${glowScale})`,
              transformOrigin: `${cx}px ${cy}px`,
              mixBlendMode: "screen",
              transition: "none",
            }}
          />
        )}
      </svg>

      {/* HTML Layer for Labels for Perfect Crispness & CSS Control */}

      {/* Circle 1 Label (Hype) */}
      <div
        style={{
          position: "absolute",
          left: label1X - 300,
          top: label1Y + label1YOffset,
          width: 600,
          height: 60,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          fontFamily,
          fontSize: "44px", // Made text bigger
          fontWeight: "bold",
          color: "#ffffff",
          opacity: label1Opacity,
          textAlign: "center",
          textShadow: "0px 2px 8px rgba(0,0,0,0.8)",
          pointerEvents: "none",
          transition: "none",
        }}
      >
        {hypeLabel}
      </div>

      {/* Circle 2 Label (Community) */}
      <div
        style={{
          position: "absolute",
          left: label2X - 300,
          top: label2Y + label2Offset,
          width: 600,
          height: 60,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          fontFamily,
          fontSize: "44px", // Made text bigger
          fontWeight: "bold",
          color: "#ffffff",
          opacity: label2Opacity,
          textAlign: "center",
          textShadow: "0px 2px 8px rgba(0,0,0,0.8)",
          pointerEvents: "none",
          transition: "none",
        }}
      >
        {communityLabel}
      </div>

      {/* Circle 3 Label (Relevance) */}
      <div
        style={{
          position: "absolute",
          left: label3X - 300,
          top: label3Y + label3Offset,
          width: 600,
          height: 60,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          fontFamily,
          fontSize: "44px", // Made text bigger
          fontWeight: "bold",
          color: "#ffffff",
          opacity: label3Opacity,
          textAlign: "center",
          textShadow: "0px 2px 8px rgba(0,0,0,0.8)",
          pointerEvents: "none",
          transition: "none",
        }}
      >
        {relevanceLabel}
      </div>

      {/* Center Highlight Label ("Worth Investing In") */}
      <div
        style={{
          position: "absolute",
          left: cx - 250,
          top: cy - 80,
          width: 500,
          height: 160,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "center",
          opacity: centerLabelOpacity,
          transform: `scale(${centerLabelScale})`,
          fontFamily,
          fontWeight: "bold",
          fontSize: "38px", // Made text bigger
          color: "#ffffff",
          textAlign: "center",
          lineHeight: "1.25",
          textShadow: "0 0 15px rgba(34, 197, 94, 0.7), 0 2px 8px rgba(0, 0, 0, 0.9)",
          pointerEvents: "none",
          transition: "none",
        }}
      >
        <div>{centerLabelLine1}</div>
        <div>{centerLabelLine2}</div>
      </div>
    </AbsoluteFill>
  );
};

export default VennDiagram;